"""Run the required PG gate, preserving reports generated by other tickets."""
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[2]
OUT = Path(__file__).resolve().parent
protected = [ROOT / name for name in ['report/w06-evidence/http-doc1.json',
    'report/w06-evidence/http-six-books.json', 'report/w14-evidence/http-contract.json']]
before = {p: p.read_bytes() for p in protected}
tracked = subprocess.check_output(['git', 'ls-files', 'src', 'scripts'], cwd=ROOT, text=True).splitlines()
source = {name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest() for name in tracked if (ROOT / name).is_file()}
receipt = {'sourceCommit': subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT, text=True).strip(),
    'main': subprocess.check_output(['git', 'rev-parse', 'main'], cwd=ROOT, text=True).strip(), 'sourceSha256': source}
command = [sys.executable, 'scripts/w05_run_tests.py', '-o', 'addopts=', '-q',
    '--basetemp=tmp/cong-w09-required-final1-20261025', '--junitxml=report/w09-required-fixes-2026-10-25/full.xml']
receipt['command'] = command
(OUT / 'gate-source.json').write_text(json.dumps(receipt, indent=2) + '\n', encoding='utf8')
env = dict(os.environ, W15_EVIDENCE_RUN='w09-required-20261025', W25_EVIDENCE_RUN='w09-required-20261025')
try:
    with (OUT / 'full.log').open('wb') as log:
        result = subprocess.run(command, cwd=ROOT, env=env, stdout=log, stderr=subprocess.STDOUT)
finally:
    folder = OUT / 'generated-contracts'
    folder.mkdir(exist_ok=True)
    rows = []
    for p, raw in before.items():
        generated = p.read_bytes()
        target = folder / p.name
        assert not target.exists()
        target.write_bytes(generated)
        assert target.read_bytes() == generated
        p.write_bytes(raw)
        assert p.read_bytes() == raw
        rows.append({'path': p.relative_to(ROOT).as_posix(), 'beforeRestoredSha256': hashlib.sha256(raw).hexdigest(),
            'generatedCopy': target.relative_to(ROOT).as_posix(), 'generatedSha256': hashlib.sha256(generated).hexdigest()})
    (OUT / 'generated-contracts.json').write_text(json.dumps(rows, indent=2) + '\n', encoding='utf8')
receipt['nativeExit'] = result.returncode
receipt['allSourceHashesUnchanged'] = all(hashlib.sha256((ROOT / name).read_bytes()).hexdigest() == value for name, value in source.items())
assert receipt['allSourceHashesUnchanged']
(OUT / 'full-exit.json').write_text(json.dumps(receipt, indent=2) + '\n', encoding='utf8')
print('Full PostgreSQL gate native exit:', result.returncode)
raise SystemExit(result.returncode)
